package com.example.lab.payment.kafka; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="processed_saga_events") public class ProcessedSagaEvent { @Id UUID eventId; @Column(nullable=false) String eventType; @Column(nullable=false) Instant processedAt=Instant.now(); protected ProcessedSagaEvent(){} public ProcessedSagaEvent(UUID id,String type){eventId=id;eventType=type;} }
